	@Test
	void leftDependentTrueConditionRetainsIndependentRightMatches() {
		assertNativeBag(query("?s ex:flag ?flag .", "ex:global ex:tag ?tag .", "?s = ex:accepted"),
				List.of(row("accepted", "tagA"), row("accepted", "tagB"),
						row("rejected", null), row("error", null)));
	}

	@Test
	void leftDependentFalseAndErrorConditionsNullExtendTheirLeftRows() {
		assertNativeBag(query("?s ex:flag ?flag .", "ex:global ex:tag ?tag .", "(?flag + 0) = 1"),
				List.of(row("accepted", "tagA"), row("accepted", "tagB"),
						row("rejected", null), row("error", null)));
	}

	@Test
	void conditionPreservesDuplicateLeftAndIndependentRightMappings() {
		assertNativeBag(query("?s ex:flag ?flag ; ex:copy ?leftCopy .",
				"ex:global ex:tag ?tag . ?tag ex:copy ?rightCopy .", "(?flag + 0) = 1"),
				List.of(row("accepted", "tagA"), row("accepted", "tagA"),
						row("accepted", "tagA"), row("accepted", "tagA"),
						row("accepted", "tagB"), row("accepted", "tagB"),
						row("rejected", null), row("error", null)));
	}

	@Test
	void independentConditionCannotReadAnInheritedSiblingBinding() {
		// The inner projection removes ?hidden before the OPTIONAL condition can see the left mapping.
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?tag WHERE {\n"
				+ "{ SELECT ?s WHERE { VALUES ?hidden { \"inside projected subquery\" } ?s ex:flag ?flag . } }\n"
				+ "OPTIONAL { { SELECT ?tag WHERE { ex:global ex:tag ?tag . } } FILTER(BOUND(?hidden)) }\n"
				+ "}";
		assertNativeBag(query,
				List.of(row("accepted", null), row("rejected", null), row("error", null)));
	}

	@Test
	void volatileConditionRunsOncePerMergedDuplicateOccurrence() {
		FunctionRegistry functions = FunctionRegistry.getInstance();
		Function previous = functions.get(VOLATILE_CONDITION).orElse(null);
		VolatileConditionFunction function = new VolatileConditionFunction();
		functions.add(function);
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?tag WHERE {\n"
				+ "VALUES ?s { ex:accepted ex:accepted }\n"
				+ "OPTIONAL { { SELECT ?tag WHERE { VALUES ?tag { ex:tagA ex:tagA } } } "
				+ "FILTER(<" + VOLATILE_CONDITION + ">(?tag)) }\n"
				+ "}";
		List<ResultRow> expected = List.of(row("accepted", "tagA"), row("accepted", "tagA"),
				row("accepted", "tagA"), row("accepted", "tagA"));
		try {
			System.setProperty(NATIVE_FLAG, "false");
			assertThat(rows(query, false)).containsExactlyInAnyOrderElementsOf(expected);
			assertThat(function.calls.get()).as("generic condition calls for four compatible occurrences").isEqualTo(4);

			function.calls.set(0);
			System.setProperty(NATIVE_FLAG, "true");
			assertThat(rows(query, true)).containsExactlyInAnyOrderElementsOf(expected);
			assertThat(function.calls.get()).as("native condition calls for four compatible occurrences").isEqualTo(4);
			assertNativeExecution(query, "LexicalReplayLeftJoin");
		} finally {
			functions.remove(function);
			if (previous != null) {
				functions.add(previous);
			}
		}
	}

