	private CloseSensitiveExistsFilter runSequentialPhysicalOptionalReopens(boolean borrowedCondition)
			throws Exception {
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			SyntheticValueSource source = SyntheticValueSource.forEvaluation((NativeLmdbQuerySource) dataset);
			NativeSlotLayout layout = new NativeSlotLayout(
					Map.of("outer", 0, "s", 1, "tag", 2, "copy", 3), null);
			layout.freeze(List.of("outer", "s", "tag", "copy"));
			RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
			source.executionContext().initializeQueryBase(row.base);
			assertThat(NativeRowSeeder.seed(row.slots, layout, row.base, source)).isTrue();
			// Force the ordinary parent loop so this exact OPTIONAL plan opens and closes once per outer row.
			row.encounterOrderRequired = true;
			NativeBooleanFilter exists = new ExistsFilter(new PatternPlan(
					Term.slot(2),
					Term.constant(id(source, "copy")),
					Term.slot(3),
					Term.unbound(),
					ContextConstraint.UNRESTRICTED,
					false,
					null,
					"",
					null,
					1D,
					source.indexAccessProfile()));
			CloseSensitiveExistsFilter closeSensitive = new CloseSensitiveExistsFilter(exists);
			ScopedNativeBooleanFilter scoped = new ScopedNativeBooleanFilter(closeSensitive, Set.of("s", "tag"));
			NativeFilterLease lease = borrowedCondition ? new NativeFilterLease() : null;
			NativeBooleanFilter condition = lease == null ? scoped : lease.borrow(scoped);
			SlotPlan outer = values(0, new long[] { id(source, "accepted"), id(source, "rejected") });
			SlotPlan left = values(1, new long[] { id(source, "accepted") });
			PatternPlan right = new PatternPlan(
					Term.constant(id(source, "global")),
					Term.constant(id(source, "tag")),
					Term.slot(2),
					Term.unbound(),
					ContextConstraint.UNRESTRICTED,
					false,
					null,
					"",
					null,
					2D,
					source.indexAccessProfile());
			OptionalMaterialization registry = source.executionContext().optionalMaterializations();
			OptionalOccurrence occurrence = new OptionalOccurrence(registry);
			try {
				OptionalRhsContract rhsContract = occurrence.contract;
				SlotPlan optional = SlotPlan.lexicalLeftJoin(left, right, new int[0], false, condition, rhsContract);
				JoinPlan parent = new JoinPlan(outer, optional);
				List<String> actual = new ArrayList<>();
				try (RowCursor cursor = parent.open(row)) {
					while (cursor.next()) {
						actual.add(term(source, row.slots[0]) + "|" + term(source, row.slots[1]) + "|"
								+ term(source, row.slots[2]));
					}
				}
				actual.sort(String::compareTo);
				assertThat(actual).containsExactly(
						EX + "accepted|" + EX + "accepted|" + EX + "tagA",
						EX + "accepted|" + EX + "accepted|" + EX + "tagB",
						EX + "rejected|" + EX + "accepted|" + EX + "tagA",
						EX + "rejected|" + EX + "accepted|" + EX + "tagB");
				assertThat(closeSensitive.calls).as("EXISTS condition evaluates after each physical reopen")
						.isEqualTo(4);
				assertThat(closeSensitive.closed).as("a physical OPTIONAL close does not close its shared condition")
						.isFalse();
				if (lease != null) {
					lease.commit();
					assertThat(closeSensitive.closed).isTrue();
				}
			} catch (IOException | RuntimeException | Error failure) {
				if (lease != null) {
					lease.abort(failure);
				}
				throw failure;
			} finally {
				try {
					occurrence.close();
				} finally {
					try {
						source.executionContext().close();
					} finally {
						row.memoryScope.close();
					}
				}
			}
			assertThat(closeSensitive.closed).isTrue();
			return closeSensitive;
		}
	}

	private static final class OptionalOccurrence implements AutoCloseable {
		private final OptionalEvaluationIdentity identity;
		private final OptionalEvaluationIdentity.Activation activation;
		private final OptionalRhsContract contract = OptionalRhsContract.unknown();

		OptionalOccurrence(OptionalMaterialization registry) {
			identity = registry.child(registry.root());
			activation = identity.activate();
		}

		@Override
		public void close() {
			try {
				activation.close();
			} finally {
				identity.close();
			}
		}
	}

	private void assertNativeBag(String query, List<ResultRow> expected) {
		System.setProperty(NATIVE_FLAG, "false");
		List<ResultRow> generic = rows(query, false);
		assertThat(generic).as("generic OPTIONAL result bag:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(expected);

		System.setProperty(NATIVE_FLAG, "true");
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		List<ResultRow> nativeRows = rows(query, true);
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get()).as("the OPTIONAL must compile natively")
				.isGreaterThan(compiledBefore);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostedBefore);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
		assertNativeExecution(query);
		assertThat(nativeRows).as("native OPTIONAL result bag:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	private List<ResultRow> rows(String query, boolean nativeExecution) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (nativeExecution) {
				prepared.setForcedLmdbExecutionStrategy("nestedLoop");
			}
			return QueryResults.asList(prepared.evaluate())
					.stream()
					.map(bindings -> new ResultRow(value(bindings, "s"), value(bindings, "tag")))
					.toList();
		}
	}

	private void assertNativeExecution(String query) {
		assertNativeExecution(query, "NativeSubquery");
	}

	private void assertNativeExecution(String query, String expectedPlanNode) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy("nestedLoop");
			GenericPlanNode plan = prepared.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			List<String> paths = new ArrayList<>();
			collectExecutionPaths(plan, paths);
			assertThat(paths).as("the parsed OPTIONAL must execute through the semantic native row plan: %s", plan)
					.contains("nestedLoop")
					.noneMatch(path -> path.startsWith("genericFallback"));
			assertThat(plan.toString()).as("the expected operand must remain in the native row plan")
					.contains("NativeRows", expectedPlanNode);
		}
	}

	private static void collectExecutionPaths(GenericPlanNode node, List<String> paths) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			for (String part : path.split("\\|")) {
				paths.add(part.trim());
			}
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collectExecutionPaths(child, paths));
		}
	}

	private static String query(String left, String right, String condition) {
		return "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?tag WHERE {\n"
				+ left + "\n"
				+ "OPTIONAL { { SELECT ?tag WHERE { " + right + " } } FILTER(" + condition + ") }\n"
				+ "}";
	}

	private static String value(BindingSet bindings, String name) {
		Value value = bindings.getValue(name);
		return value == null ? null : value.stringValue();
	}

	private static ResultRow row(String subject, String tag) {
		return new ResultRow(EX + subject, tag == null ? null : EX + tag);
	}

	private static SlotPlan values(int slot, long[] values) {
		ValuesRow[] rows = new ValuesRow[values.length];
		for (int i = 0; i < values.length; i++) {
			rows[i] = new ValuesRow(new int[] { slot }, new long[] { values[i] });
		}
		return new ValuesPlan(rows);
	}

	private static long id(SyntheticValueSource source, String localName) {
		return source.idOf(SimpleValueFactory.getInstance().createIRI(EX + localName));
	}

	private static String term(SyntheticValueSource source, long id) {
		return source.lazyValue(id).stringValue();
	}

	private record ResultRow(String subject, String tag) {
	}

	private static final class CloseSensitiveExistsFilter implements NativeBooleanFilter {
		private final NativeBooleanFilter delegate;
		private int calls;
		private int closeCount;
		private boolean closed;

		private CloseSensitiveExistsFilter(NativeBooleanFilter delegate) {
			this.delegate = delegate;
		}

		@Override
		public boolean accept(RowState row) {
			if (closed) {
				throw new IllegalStateException("OPTIONAL condition was closed before its next physical reader");
			}
			calls++;
			return delegate.accept(row);
		}

		@Override
		public NativePredicateCapabilities capabilities() {
			return delegate.capabilities();
		}

		@Override
		public void close() {
			if (!closed) {
				closed = true;
				closeCount++;
				delegate.close();
			}
		}
	}

	private static final class VolatileConditionFunction implements Function {
		private final AtomicInteger calls = new AtomicInteger();

		@Override
		public String getURI() {
			return VOLATILE_CONDITION;
		}

		@Override
		public Determinism getDeterminism() {
			return Determinism.VOLATILE;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... arguments) throws ValueExprEvaluationException {
			if (arguments.length != 1) {
				throw new ValueExprEvaluationException("Expected one OPTIONAL tag");
			}
			calls.incrementAndGet();
			return valueFactory.createLiteral(true);
		}
	}
